//! System relations PGArbor cannot serve yet. Lease CAT-37. Scanning one fails with 0A000 (via the
//! inventory-counted `PgError::unimplemented`) so that a query touching it reports exactly which
//! catalog is missing instead of silently returning no rows. The list (with reasons) is generated by
//! `gen/classify_vrel.py` into `unsupported_list.inc`:
//! `pg_amop`, `pg_amproc`, `pg_conversion`, `pg_init_privs`, `pg_ts_*`, `pg_aios`,
//! `pg_backend_memory_contexts`, `pg_config`, `pg_shmem_allocations*`, server-wide `pg_stat_*`
//! (archiver, bgwriter, checkpointer, database, database_conflicts, io, slru, wal), the two timezone
//! views, `pg_wait_events`, and the four static `information_schema.sql_*` tables.
//!
//! `scan` implementation: look the OID up in `UNSUPPORTED_REASONS` and return
//! `Err(PgError::unimplemented("CAT-37", format!("system relation {qualified name}: {reason}")))`.
//! As relations become implementable they are MOVED to a producer file (edit
//! `gen/classify_vrel.py`, regenerate, add the producer): good first candidates are `pg_timezone_names` /
//! `pg_timezone_abbrevs` (data in `pgarbor_types::datetime`), `pg_stat_database` (one row per database
//! with xact counters from the engine), `pg_config`, the `sql_*` tables (static data dumped from the
//! oracle) and `pg_amop`/`pg_amproc` (dump from the oracle into `gen/ref`).
use super::{Row, ScanContext, ScanRequest, VirtualRelation};
use crate::builtin::relid;
use pgarbor_common::{Oid, PgError, Result};

/// A system relation that is not served yet.
// CONTRACT
#[derive(Clone, Copy, Debug)]
pub struct UnsupportedRelation(pub Oid);

impl VirtualRelation for UnsupportedRelation {
    fn oid(&self) -> Oid {
        self.0
    }
    #[allow(unused_variables)]
    fn scan(&self, ctx: &ScanContext, req: &ScanRequest) -> Result<Vec<Row>> {
        Err(PgError::unimplemented("CAT-37", "unsupported system relation"))
    }
}

include!("unsupported_list.inc");
